  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["m", "massa do skatista, em kg"],
    ["g", "aceleração da gravidade, 10 m/s² (dado do enunciado)"],
    ["h", "desnível entre o ponto mais alto e o mais baixo, 2,45 m"],
    ["v", "velocidade no ponto mais baixo, em m/s"],
    ["energia potencial", "energia guardada por estar em um lugar alto"],
    ["energia cinética", "energia que o corpo tem por estar em movimento"],
    ["energia mecânica", "soma da energia cinética com a potencial"],
    ["repouso", "parado, velocidade zero"]
